with open('generate_all.py', 'r', encoding='utf-8') as f:
    gen_code = f.read()

pos = gen_code.find('additional_translations = [')
if pos != -1:
    pos_insert = pos + len('additional_translations = [\n')
    extra_str = '\n'.join([f"    ({repr(ru)}, {repr(en)}, {repr(tr)})," for ru, en, tr in final_10]) + '\n'
    new_code = gen_code[:pos_insert] + extra_str + gen_code[pos_insert:]
    with open('generate_all.py', 'w', encoding='utf-8') as f:
        f.write(new_code)
    print("generate_all.py updated with final 10!")
